        if c in seen: continue
        stack=[c]; comp=set()
        while stack:
            p=stack.pop()
            if p in seen: continue
            seen.add(p); comp.add(p)
            r,cc=p
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    q=(r+dr,cc+dc)
                    if q in cells and q not in seen: stack.append(q)
        res.append(sorted(comp))
